107 | /** Returns all legal two-tile combinations in a hand that form a chi with a discard. */
108 | export function chiOptions(hand, discard) {
109 |   const { suit, rank, honor } = tileInfo(discard);
110 |   if (honor) return [];
111 |   const options = [];
112 |   for (const [a, b] of [[rank - 2, rank - 1], [rank - 1, rank + 1], [rank + 1, rank + 2]]) {
113 |     if (a < 1 || b > 9) continue;
114 |     const first = `${a}${suit}`, second = `${b}${suit}`;
115 |     const available = [...hand];
116 |     const one = available.indexOf(first); if (one < 0) continue;
117 |     available.splice(one, 1);
118 |     if (available.includes(second)) options.push([first, second]);
119 |   }
120 |   return options;
121 | }
