127 | export function chooseDiscard(hand) {
128 |   const counts = countsFor(hand);
129 |   const isolated = hand.filter(tile => {
130 |     const { suit, rank, honor } = tileInfo(tile);
131 |     if (honor) return counts.get(tile) === 1;
132 |     return counts.get(tile) === 1 && !hand.includes(`${rank - 1}${suit}`) && !hand.includes(`${rank + 1}${suit}`) && !hand.includes(`${rank - 2}${suit}`) && !hand.includes(`${rank + 2}${suit}`);
133 |   });
134 |   return sortTiles(isolated.length ? isolated : hand)[0];
