export const BACKUP_VERSION = 1;
export const MAX_HISTORY = 30;
const validSpeeds = ["slow", "normal", "fast"], validTileText = ["standard", "large"], validMotion = ["system", "reduce", "full"];

export const defaultPreferences = () => ({ speed: "normal", tileText: "standard", motion: "system" });
export function isValidPreferences(value) { return !!value && typeof value === "object" && validSpeeds.includes(value.speed) && validTileText.includes(value.tileText) && validMotion.includes(value.motion); }
export function isValidHistory(value) {
  return Array.isArray(value) && value.length <= MAX_HISTORY && value.every(entry => entry && typeof entry === "object" && typeof entry.id === "string" && typeof entry.outcome === "string" && typeof entry.winner === "string" && typeof entry.finishedAt === "string" && !Number.isNaN(Date.parse(entry.finishedAt)) && Number.isInteger(entry.turnCount) && entry.turnCount >= 0 && typeof entry.note === "string" && entry.note.length <= 280);
}
export function normalizeHistory(value) { return isValidHistory(value) ? value.slice(0, MAX_HISTORY) : []; }
export function recordFinishedHand(history, entry) {
  if (!isValidHistory(history) || !isValidHistory([{ ...entry, note: entry.note ?? "" }])) return history;
  if (history.some(item => item.id === entry.id)) return history;
  return [{ ...entry, note: entry.note ?? "" }, ...history].slice(0, MAX_HISTORY);
}
export function createBackup(round, preferences, history) { return { version: BACKUP_VERSION, round, preferences, history }; }
export function validateBackup(value) {
  if (!value || typeof value !== "object" || value.version !== BACKUP_VERSION || !isValidRound(value.round) || !isValidPreferences(value.preferences) || !isValidHistory(value.history)) return null;
  return structuredClone(value);
}
export function readJson(storage, key) { try { const raw = storage?.getItem(key); return raw === null ? { value: null } : { value: JSON.parse(raw) }; } catch (error) { return { value: null, error }; } }
export function writeJson(storage, key, value) { try { storage?.setItem(key, JSON.stringify(value)); return !!storage; } catch { return false; } }

import test from "node:test";
import assert from "node:assert/strict";
