const round = { wall:["1m"], phase:"discard", turn:0, lastDiscard:null, lastDiscarder:null, turnStartedByDraw:true, result:null, players:Array.from({ length:4 }, () => ({ hand:[], melds:[], discards:[] })) };
const entry = { id:"hand-1", outcome:"Win", winner:"You · East", finishedAt:"2026-01-01T00:00:00.000Z", turnCount:4, note:"" };

test("finished hands are unique and history retains the newest 30", () => {
  let history=[]; history=recordFinishedHand(history,entry); history=recordFinishedHand(history,entry);
  assert.equal(history.length,1);
  for(let i=2;i<=31;i++) history=recordFinishedHand(history,{...entry,id:`hand-${i}`});
  assert.equal(history.length,30); assert.equal(history[0].id,"hand-31"); assert.equal(history.at(-1).id,"hand-2");
});
