  let state={wall,players,turn:0,phase:"discard",lastDiscard:null,lastDiscarder:null,turnStartedByDraw:true,result:null},claims=0,steps=0;
  const inventory=round=>[...round.wall,...round.players.flatMap(player=>[...player.hand,...player.discards,...player.melds.flat()])];
  const baseline=[...inventory(state)].sort();
  while(state.phase!=="ended"&&steps++<1000){
    assert.deepEqual(inventory(state).sort(),baseline);
    if(state.phase==="draw"){state=drawTransition(state);continue}
    if(state.phase==="discard"){state=discardTransition(state,state.turn,chooseDiscard(state.players[state.turn].hand));continue}
    const outcome=settleClaims(state);if(outcome.kind==="claim")claims++;state=applySettlement(state,outcome);
  }
  assert.ok(steps<1000);assert.equal(state.phase,"ended");assert.deepEqual(inventory(state).sort(),baseline);assert.ok(claims>0);
});
